  stmts := ARRAY_APPEND(:stmts, REPLACE(REPLACE('DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20072,''Existing app requires explicit migration; source is preserved''); BEGIN SHOW STREAMLITS LIKE ''TRANSFORMATION_PIPELINE_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''TRANSFORMATION_PIPELINE_APP''; IF (:present_count>0) THEN SHOW STREAMLITS LIKE ''TRANSFORMATION_PIPELINE_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''TRANSFORMATION_PIPELINE_APP'' AND "comment"=''oneshot-source:18_transformation_pipeline''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE STREAMLIT __TARGET__.TRANSFORMATION_PIPELINE_APP FROM ''@__TARGET__.APP_STAGE/source/9bcd13b383e17f75/'' MAIN_FILE=''streamlit_app.py'' QUERY_WAREHOUSE=__WAREHOUSE__ RUNTIME_NAME=''SYSTEM$WAREHOUSE_RUNTIME'' COMMENT=''oneshot-source:18_transformation_pipeline''; ALTER STREAMLIT __TARGET__.TRANSFORMATION_PIPELINE_APP ADD LIVE VERSION FROM LAST; END IF; END', '__TARGET__', :tgt), '__WAREHOUSE__', :wh));
